
const WORDS=[{"id": 0, "w": "锯", "p": "jù", "t": "动词／名词", "m": "cưa; cái cưa", "coll": "一把锯、锯开木板", "s": "爸爸用一把锯把木板锯成了两段。"}, {"id": 1, "w": "筐", "p": "kuāng", "t": "名词", "m": "giỏ, sọt", "coll": "一只筐、一筐水果", "s": "爷爷提着一只筐，准备去地里摘菜。"}, {"id": 2, "w": "训练", "p": "xùnliàn", "t": "动词", "m": "huấn luyện", "coll": "参加训练、训练队员", "s": "教练正在操场上训练队员。"}, {"id": 3, "w": "缺乏", "p": "quēfá", "t": "动词", "m": "thiếu, không đủ", "coll": "缺乏经验、缺乏信心", "s": "他虽然缺乏经验，但学习得很认真。"}, {"id": 4, "w": "项目", "p": "xiàngmù", "t": "名词", "m": "hạng mục", "coll": "工程项目、学习项目", "s": "这个项目需要几个部门共同合作。"}, {"id": 5, "w": "桃", "p": "táo", "t": "名词", "m": "(trái) đào", "coll": "一个桃、桃树", "s": "奶奶买了几个桃，洗干净后放在了盘子里。"}, {"id": 6, "w": "装", "p": "zhuāng", "t": "动词", "m": "đựng, để vào", "coll": "装东西、装进袋子", "s": "她把买来的水果装进了袋子。"}, {"id": 7, "w": "启发", "p": "qǐfā", "t": "动词", "m": "gợi ý", "coll": "受到启发、启发思考", "s": "这篇文章给了我很多启发，让我想到了新的方法。"}, {"id": 8, "w": "安装", "p": "ānzhuāng", "t": "动词", "m": "lắp đặt, gắn", "coll": "安装软件、安装设备", "s": "工作人员正在给教室安装新的投影设备。"}, {"id": 9, "w": "栏杆", "p": "lángān", "t": "名词", "m": "hàng lan can", "coll": "一排栏杆、靠近栏杆", "s": "孩子站在栏杆旁边，看着河里的小鱼。"}, {"id": 10, "w": "甲", "p": "jiǎ", "t": "名词", "m": "người (đội) thứ nhất", "coll": "甲队、甲方", "s": "比赛开始后，甲队首先发起了进攻。"}, {"id": 11, "w": "乙", "p": "yǐ", "t": "名词", "m": "người (đội) thứ hai", "coll": "乙队、乙方", "s": "上半场结束时，乙队比甲队多得了两分。"}, {"id": 12, "w": "工具", "p": "gōngjù", "t": "名词", "m": "công cụ", "coll": "使用工具、一套工具", "s": "修理自行车前，他先准备好了工具。"}, {"id": 13, "w": "投篮", "p": "tóu lán", "t": "动词", "m": "ném bóng vào rổ", "coll": "练习投篮、投篮姿势", "s": "放学后，他每天都在操场上练习投篮。"}, {"id": 14, "w": "踩", "p": "cǎi", "t": "动词", "m": "giẫm, đạp", "coll": "踩到脚、不要踩草地", "s": "车上人很多，他不小心踩到了我的脚。"}, {"id": 15, "w": "一再", "p": "yízài", "t": "副词", "m": "nhiều lần, hết lần này đến lần khác", "coll": "一再提醒、一再解释", "s": "老师一再提醒我们，交作业前要仔细检查。"}, {"id": 16, "w": "重复", "p": "chóngfù", "t": "动词", "m": "lặp lại", "coll": "重复一遍、避免重复", "s": "我刚才没听清楚，请您再重复一遍。"}, {"id": 17, "w": "断断续续", "p": "duànduànxùxù", "t": "形容词", "m": "không liên tục, gián đoạn", "coll": "断断续续地说、断断续续的声音", "s": "信号不好，他的声音从电话里断断续续地传来。"}, {"id": 18, "w": "激烈", "p": "jīliè", "t": "形容词", "m": "kịch liệt, sôi nổi", "coll": "激烈的比赛、讨论激烈", "s": "两队实力相当，比赛进行得十分激烈。"}, {"id": 19, "w": "气氛", "p": "qìfēn", "t": "名词", "m": "bầu không khí", "coll": "气氛热烈、活跃气氛", "s": "大家一边唱歌一边拍手，晚会的气氛十分热烈。"}, {"id": 20, "w": "何况", "p": "hékuàng", "t": "连词", "m": "huống hồ, huống chi", "coll": "更何况、何况是", "s": "这件事大人做起来都很难，何况是一个孩子呢？"}, {"id": 21, "w": "球迷", "p": "qiúmí", "t": "名词", "m": "người mê bóng", "coll": "一个球迷、真正的球迷", "s": "他是一个真正的球迷，每场重要比赛都不愿错过。"}, {"id": 22, "w": "工程师", "p": "gōngchéngshī", "t": "名词", "m": "kỹ sư", "coll": "一位工程师、软件工程师", "s": "那位工程师正在向大家介绍机器的使用方法。"}, {"id": 23, "w": "机器", "p": "jīqì", "t": "名词", "m": "máy móc", "coll": "一台机器、操作机器", "s": "这台机器出了问题，工程师正在检查。"}, {"id": 24, "w": "顺畅", "p": "shùnchàng", "t": "形容词", "m": "trôi chảy", "coll": "交通顺畅、交流顺畅", "s": "提前说明要求，可以让双方的交流更加顺畅。"}, {"id": 25, "w": "幼儿园", "p": "yòu'éryuán", "t": "名词", "m": "nhà trẻ", "coll": "上幼儿园、幼儿园老师", "s": "妹妹今年开始上幼儿园了。"}, {"id": 26, "w": "好奇", "p": "hàoqí", "t": "形容词", "m": "hiếu kỳ, tò mò", "coll": "对……好奇、充满好奇", "s": "孩子们对这个新玩具都感到十分好奇。"}, {"id": 27, "w": "何必", "p": "hébì", "t": "副词", "m": "(chỉ sự không cần) hà tất, cần gì", "coll": "何必着急、何必再问", "s": "事情已经解决了，你何必再着急呢？"}, {"id": 28, "w": "多亏", "p": "duōkuī", "t": "动词", "m": "may mà (có), nhờ có", "coll": "多亏帮助、多亏了你", "s": "多亏你的提醒，我才没有错过火车。"}, {"id": 29, "w": "连忙", "p": "liánmáng", "t": "副词", "m": "ngay lập tức", "coll": "连忙道谢、连忙起身", "s": "看到老师进来，他连忙站了起来。"}, {"id": 30, "w": "瞧", "p": "qiáo", "t": "动词", "m": "nhìn", "coll": "瞧一瞧、瞧见了", "s": "你瞧，那边的花开得多漂亮！"}, {"id": 31, "w": "困扰", "p": "kùnrǎo", "t": "动词", "m": "làm phiền, gây rối", "coll": "受到困扰、困扰很久", "s": "这个问题已经困扰了他很长时间。"}, {"id": 32, "w": "思维", "p": "sīwéi", "t": "名词／动词", "m": "tư duy; suy nghĩ", "coll": "思维方式、培养思维能力", "s": "不同的生活经历会影响一个人的思维方式。"}, {"id": 33, "w": "呆", "p": "dāi", "t": "形容词／动词", "m": "đần độn, ngu ngốc; nán lại, ở lại", "coll": "呆一会儿、呆在家里", "s": "外面下雨了，我们先在这里呆一会儿吧。"}, {"id": 34, "w": "造成", "p": "zàochéng", "t": "动词", "m": "tạo thành, gây ra", "coll": "造成损失、造成误会", "s": "由于沟通不够，这件事造成了不必要的误会。"}, {"id": 35, "w": "仿佛", "p": "fǎngfú", "t": "副词／动词", "m": "dường như; giống như", "coll": "仿佛看见、仿佛回到从前", "s": "看到这张老照片，我仿佛又回到了童年。"}, {"id": 36, "w": "阻碍", "p": "zǔ'ài", "t": "动词", "m": "ngăn cản, cản trở", "coll": "阻碍发展、阻碍进步", "s": "缺乏信心有时会阻碍一个人的进步。"}];
